(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["es"] = {"ui":{"skip":"Saltar al contenido","back":"← Volver a AI-gile","lang.button":"Idioma: {name}","lang.dialog":"Elige un idioma","lang.search":"Buscar idiomas","lang.none":"Ningún idioma coincide","lang.notYet":"{name} aún no está traducido","theme.aria":"Cambiar entre tema claro y oscuro","theme.toLight":"Cambiar al tema claro","theme.toDark":"Cambiar al tema oscuro","index.title":"AI-gile: tu equipo de desarrollo con IA, en un solo tablero","index.description":"AI-gile es un tablero kanban para equipos de programación con IA. Trabajan mientras duermes; tú recibes un montón corto de cosas que decidir, probar y aceptar.","hero.logoAlt":"Icono del tablero de AI-gile","hero.h1.html":"Tu equipo de desarrollo con IA, en un solo&nbsp;tablero.","hero.alpha":"🐣 Preálfa cerrada","hero.alphaTitle":"Temprano y sin terminar: ¡gracias por probarlo!","hero.lede":"Construyen mientras duermes. Te despiertas con un montón corto: un par de preguntas, un par de cosas que probar, un rombo morado o dos. Clic, aceptar y de vuelta a tu café.","dl.windows":"App para Windows","dl.browser":"Úsalo en el navegador","dl.soon":"Próximamente","dl.notify":"🔔 Avísame cuando abra","dl.notifySmall":"Alfa o beta","hero.secondary":"Ágil, pero el equipo nunca necesita un café de stand-up. (Aun así, hacen stand-ups.)","pitch.h2":"AI-gile en tantas palabras como quieras","pitch.lede":"Elige una longitud, desde una palabra hasta 144. Cada longitud es su propia descripción, escrita para ese tamaño. Arrastra el control deslizante o usa las flechas del teclado.","pitch.rangeLabel":"Longitud en palabras","pitch.dice":"🎲 otra versión","pitch.words.one":"{n} palabra","pitch.words.other":"{n} palabras","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letras","pitch.chars.one":"{n} carácter","pitch.chars.other":"{n} caracteres","count.line.html.one":"{n} tarjeta en el tablero ahora mismo","count.line.html.other":"{n} tarjetas en el tablero ahora mismo","features.aria":"Qué hace","f.pile.h":"Un solo montón para ti","f.pile.html":"<b>Para ti</b> reúne todo lo que te está esperando, de todos los proyectos: preguntas, cosas que probar, tareas que solo puede hacer una persona. Tu cola te dice qué toca ahora y cuánto lleva.","f.sleep.h":"Equipos que trabajan mientras duermes","f.sleep.p":"Cada proyecto tiene un líder y un equipo de agentes de IA. Comenta una tarjeta y el equipo se despierta, hace el trabajo y te la devuelve con pasos que una persona cansada pueda seguir.","f.tester.h":"Primero revisa un tester de IA","f.tester.p":"Antes de que algo llegue a ti, un tester sigue los pasos en una copia de la app y muestra lo que vio, con una captura. Repasa las que pasaron y acepta con un clic.","f.proof.h":"Pruebas, no promesas","f.proof.p":"Cada entrega muestra qué cambió: los archivos, el diff, las capturas. Sin abrir cada app para saber si está listo.","f.chat.h":"Charla con tus líderes","f.chat.p":"Una barra al estilo Discord: un icono por proyecto, rombos morados para lo que te necesita. Cuéntale una idea a un líder; la convierte en tarjetas y un plan, con un botón ✅ Adelante.","f.tidy.h":"Se mantiene ordenado solo","f.tidy.p":"Las tarjetas relacionadas se funden en una, los títulos enrevesados se arreglan y una revisión de tokens mantiene el código ligero. Menos cosas entre las que cambiar, menos en qué pensar.","f.private.h":"Tuyo, en tu ordenador","f.private.li1":"El tablero funciona en tu propio equipo y solo te responde a ti.","f.private.li2":"Los mensajes privados entre personas están cifrados de extremo a extremo.","f.private.li3":"Sin cuentas, sin rastreadores, sin cookies.","f.lang.h":"En tu idioma","f.lang.p":"Más de 120 idiomas, del neerlandés, el galés y el japonés al pirata, Yoda y el klingon, con un cambio rápido de vuelta al inglés para las palabras de desarrollo.","tl.aria":"Cronología desde la primera conversación hasta la hoja de ruta","tl.h2":"Del primer chat a lo que viene","tl.lede":"Fechas y horas reales, en tu propia zona horaria. Después de hoy es el plan, sin fechas prometidas.","tl.today":"Hoy","tl.planned":"previsto","tl.cards.one":"{n} tarjeta","tl.cards.other":"{n} tarjetas","join.h2":"Súmate","join.lede":"AI-gile lo construyen una persona pequeña y un montón de agentes pacientes. Por ahora es privado, en una alfa cerrada con amigos. ¿Quieres probarlo cuando se abra?","join.btn":"Registrar interés","join.small":"Te escribiremos al correo, nada más","footer.tag":"AI-gile. Sin rastreadores, sin cookies, sin café de stand-up.","footer.licence":"Licencia comercial","footer.status":"Estado","form.sending":"Enviando…","form.failed":"No ha funcionado: inténtalo de nuevo más tarde.","form.offline":"No se pudo contactar con AI-gile: inténtalo de nuevo más tarde.","interest.title":"AI-gile: avísame cuando abra la alfa","interest.description":"Deja tu correo para saber cuándo abre la alfa o la beta cerrada de AI-gile.","interest.h1":"🔔 Avísame cuando abra","interest.lede":"AI-gile está en preálfa cerrada. Deja tu correo y te escribiremos una sola vez, cuando haya un hueco para ti.","interest.email":"Tu correo","interest.which":"¿Qué prueba?","interest.alpha":"Alfa cerrada: temprana, tosca, con muchos cambios","interest.beta":"Beta: más estable, más adelante","interest.both":"Cualquiera, la que llegue antes","interest.submit":"Apúntame a la lista","interest.thanks":"¡Gracias! Estás en la lista.","licence.title":"AI-gile: licencia comercial","licence.description":"¿Usas AI-gile en tu negocio? Solicita una licencia comercial gratuita.","licence.h1":"📜 Licencia comercial","licence.lede":"¿Usas AI-gile en el trabajo? Cuéntanos quién eres y a qué te dedicas. Si hace algo de bien, la licencia es gratuita.","licence.company":"Empresa","licence.website":"Sitio web","licence.what":"A qué te dedicas","licence.how":"Cómo ayuda al mundo","licence.email":"Correo","licence.submit":"Solicitar","licence.thanks":"¡Gracias! Te responderemos por correo.","status.title":"Estado de AI-gile","status.h1":"Estado de AI-gile","status.quiet":"Todo tranquilo","status.checking":"Comprobando…","status.offline":"No se puede contactar con el servicio de estado ahora mismo (reintentando)","status.updated":"actualizado {ago}","status.justNow":"ahora mismo","status.min":"hace {n} min","status.hours":"hace {n} h","status.days":"hace {n} d","live.h2":"Míralo construirse, en directo","live.caption":"Cada tarjeta está oculta: ves la forma del trabajo, no las palabras.","live.watching.one":"en directo: {n} mirando","live.watching.other":"en directo: {n} mirando","live.offline":"El tablero en directo está tomando aire. Vuelve pronto.","live.cols":"Backlog|Por hacer|En curso|El equipo revisa|Para que lo pruebes|Para el equipo|Hecho","live.last.now":"Última tarjeta movida hace un momento","live.last.min.one":"Última tarjeta movida hace {n} min","live.last.min.other":"Última tarjeta movida hace {n} min","live.last.hour.one":"Última tarjeta movida hace {n} hora","live.last.hour.other":"Última tarjeta movida hace {n} horas","live.last.day.one":"Última tarjeta movida hace {n} día","live.last.day.other":"Última tarjeta movida hace {n} días"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegado."]},{"n":2,"texts":["Kanban robótico.","Agentes, ordenados.","Ideas, construidas."]},{"n":3,"texts":["Kanban para robots.","Ideas que funcionan.","Kanban gratis, local."]},{"n":5,"texts":["Un tablero kanban llevado por agentes.","Tú escribes. Los agentes construyen.","Gratis, local, probado, algo disparatado."]},{"n":8,"texts":["Un tablero kanban gratuito donde trabajan agentes de IA.","Escribe una idea. Los agentes la construyen. Tú aceptas.","Agilidad para una persona y muchos robots pacientes."]},{"n":13,"texts":["Un tablero kanban en tu ordenador donde los agentes de IA recogen las tarjetas.","Escribe una idea. Un equipo de agentes la construye. Un tester la revisa.","Gratis, sin cuentas ni rastreadores: un tablero, unos cuantos robots y tú al mando."]},{"n":21,"texts":["AI-gile es un tablero kanban para trabajar con agentes de programación con IA. Ellos recogen las tarjetas; tú las pruebas y las aceptas.","Cada proyecto tiene un líder y un equipo de agentes de IA. Comenta cualquier tarjeta y el equipo se pone manos a la obra.","Un tablero personal y gratuito de tareas que funciona en tu propio ordenador. Quienes trabajan son robots. Quien dice que sí eres tú."]},{"n":34,"texts":["Pones ideas en un tablero. Un equipo de agentes de IA las convierte en funciones que andan, las prueba y te las devuelve con pasos para probarlas. Nada se da por hecho hasta que tú lo digas.","AI-gile es un tablero kanban casero que Rich construyó con mucha ayuda de los agentes que ahora gestiona. Es gratis, funciona en tu ordenador y se comparte con amigos, no se vende.","Imagina un tablero kanban normal, con columnas desde el Backlog hasta Hecho, salvo que las tarjetas las recogen agentes de IA. Cuentan cómo van, preguntan cuando se atascan y siempre esperan tu visto bueno."]},{"n":55,"texts":["AI-gile es un tablero kanban cuyo equipo está hecho de agentes de IA. Cada proyecto tiene un líder que planifica el trabajo y ayudantes que lo construyen. Cuando una función está lista, un tester de IA la prueba y hace una captura, y luego llega a tu montón. Acéptala, o comenta y la rehacen.","Empezó como la forma que tenía una persona de seguir muchas sesiones de programación con IA a la vez, y acabó siendo un tablero de verdad. Funciona en tu equipo, no pide cuenta y no tiene rastreadores. Es gratis para amigos y curiosos. También está sin terminar, así que espera aristas y alguna sorpresa.","Esta es la versión sincera. Las ideas tienes que tenerlas tú, y los resultados tienes que comprobarlos tú. Lo que hay entre medias lo hace AI-gile: ordena las tarjetas, despierta al agente adecuado cuando comentas, enseña exactamente qué ha cambiado y lo reúne todo en un montón corto para ti."]},{"n":89,"texts":["AI-gile es un tablero kanban gratuito que funciona en tu propio ordenador. En lugar de personas, cada proyecto tiene un equipo de agentes de IA: un líder que convierte tus ideas en tarjetas y un plan, y ayudantes que las recogen por orden de prioridad. Cuando algo está construido, un tester de IA sigue los pasos de prueba y te enseña lo que vio. Después espera en un único montón llamado Para ti. Lo aceptas, o comentas y el equipo lo intenta otra vez. Nada llega nunca a Hecho sin ti.","Algunas cosas que quizá no esperas. Una guardia nocturna mantiene llena la columna Por hacer mientras duermes, eligiendo tarjetas que no necesitan una respuesta tuya. Un contador de tokens muestra cuánto han gastado los agentes hoy y esta semana, y el Modo sin tokens les dice que dejen de gastar. Puedes escribir a tus amigos, y los mensajes privados van cifrados de extremo a extremo. El tablero habla unos 120 idiomas, entre ellos neerlandés, flamenco, pirata y klingon. Nada de esto cuesta un céntimo, y nadie intenta vendértelo.","AI-gile es un proyecto pequeño y personal, no una empresa. Rich quería cuidar varios proyectos de programación con IA sin abrir cada app para ver cómo iban, así que él y los agentes construyeron un tablero para eso y luego lo usaron para construir el resto de sí mismo. Está en preálfa cerrada, lo que significa que funciona, casi siempre, para un puñado de amigos. No hay página de precios, ni boletín, ni plan de crecimiento. Si te suena útil, puedes pedir probarlo cuando se abra un poco más."]},{"n":144,"texts":["AI-gile es un tablero kanban para una persona y muchos agentes de IA. Funciona en tu propio ordenador y es totalmente gratis. Añades proyectos, y cada proyecto recibe un líder y un pequeño equipo. Charlas con el líder, un poco como en Discord, y le describes una idea; el líder la convierte en tarjetas y un plan, y espera a que pulses Adelante. El equipo va despachando las tarjetas por orden de prioridad, con una sencilla línea de comandos pensada para modelos de lenguaje. Antes de que nada vuelva a ti, un tester de IA sigue los pasos en una copia de la app y adjunta una captura. El trabajo terminado llega a tu montón con los archivos cambiados y el diff. Lo aceptas, o dejas un comentario y el equipo se despierta y vuelve a intentarlo. Solo tú puedes mover una tarjeta a Hecho.","Un día con AI-gile, más o menos. Por la tarde dejas unos cuantos comentarios: este botón está donde no toca, esa lista debería ir ordenada, ¿podríamos tener un modo oscuro? Te vas a la cama. Los agentes leen los comentarios, hacen los cambios, los prueban y te los devuelven. Si Por hacer se queda vacía, la guardia nocturna la llena desde el backlog con tarjetas que no necesitan respuesta tuya. Por la mañana hay un único montón corto: un par de preguntas y unas cuantas cosas que probar, cada una con pasos que una persona dormida puede seguir y una captura de que funciona. Vas pasando, aceptas las buenas y devuelves el resto. Un contador de tokens muestra lo que se gastó, y el Modo sin tokens está para las semanas justas. Luego desayunas, algo en lo que los agentes todavía no pueden ayudar.","Primero, lo que AI-gile no es. No es una startup, no está a la venta y nadie recoge tus datos. Es un tablero gratuito que funciona en tu ordenador, sin cuentas, sin rastreadores y sin cookies. Lo que sí es: un único sitio ordenado para ver todos tus proyectos de programación con IA a la vez, con un equipo de agentes que hace las tarjetas y tú tomando las decisiones. Une las tarjetas relacionadas, arregla los títulos enrevesados y vigila lo ligero que se mantiene el código. Habla unos 120 idiomas, del neerlandés y el flamenco al pirata y el klingon. Los amigos pueden escribirse en privado y cifrado. Lo construyeron Rich y un gran número de agentes pacientes, casi siempre usándose a sí mismo. Está en preálfa cerrada, así que es tosco en algunos puntos. Si te parece divertido, pídelo con educación y quizá entres pronto."]}],"quips":{"1":"Una palabra. Atrevido. Quizá demasiado.","3":"Tres palabras. Ya más sincero que la mayoría de las páginas de producto.","8":"Ocho palabras. Aún más corto que un stand-up.","21":"Por cierto, las longitudes son puntos de historia. Cómo no.","55":"Cincuenta y cinco palabras. Mientras las leías se terminaron dos tarjetas.","144":"Esa es la larga. No existe el 233. Los agentes se han ido a dormir."}},"timeline":{"first-idea.name":"La primera idea","first-idea.line":"La primerísima conversación, antes de que existiera una línea de código.","first-board.name":"Primer tablero","first-board.line":"Un tablero que sigue su propia construcción: tarjetas, columnas, arrastrar y soltar, proyectos.","team-roles.name":"Equipo y roles","team-roles.line":"Perfiles de agentes, plantillas de equipo, espacios y quién hace qué.","install.name":"Instalación y versiones","install.line":"Un zip que un amigo puede instalar, con autoactualización, canales y vuelta atrás.","usage-saver.name":"Ahorro de uso","usage-saver.line":"Medir lo que cuestan las ejecuciones, mantener el código ligero, cuidar tu límite.","friends.name":"Amigos y compartir","friends.line":"Mensajes privados, un relé cifrado, invitaciones, roles y proyectos compartidos.","languages.name":"Idiomas","languages.line":"Cada texto de pantalla en un archivo de idioma, primero neerlandés y flamenco.","ai-tester.name":"Tester de IA","ai-tester.line":"Un tester revisa primero cada entrega y muestra lo que vio.","website.name":"La web","website.line":"aigile.lol, el adelanto y esta cronología.","streaming.name":"Chat y streaming","streaming.line":"Discord, Twitch, OBS, modo streamer, GIF y emojis.","no-ai.name":"Edición sin IA","no-ai.line":"Un tablero para quien programa sin IA, y tableros públicos.","night-watch.name":"Guardia nocturna","night-watch.line":"Un vigilante y un Scrum Master mantienen a los equipos en su tarea mientras duermes.","p-more.name":"Todo lo demás","p-more.line":"Ideas más pequeñas que aún esperan su turno.","p-android.name":"Móvil y Android","p-android.line":"Llegar a tu tablero desde el móvil y, después, una app nativa de Android.","p-release.name":"Alfa y más allá","p-release.line":"Alfa cerrada, la web en vivo y luego la beta.","p-languages.name":"Más idiomas","p-languages.line":"Más de cien idiomas y un modo de inmersión para quien aprende.","p-engines.name":"Más motores de IA","p-engines.line":"Elige Claude, Codex o Gemini para cada agente.","p-pro.name":"Práctica profesional","p-pro.line":"Etiquetas de riesgo, puertas de fusión, tarjetas de incidente y barreras de seguridad.","p-self.name":"Cuidarte a ti","p-self.line":"Modo cansado, recordatorios de autocuidado y las 4:20.","p-servers.name":"Servidores y escala","p-servers.line":"Ajustes globales del servidor, roles y planificación para crecer.","p-livestream.name":"Extras de streaming","p-livestream.line":"Chat de Twitch, emojis propios y una vista en vivo pública."},"words":{"button":"📖 Palabras técnicas","h":"📖 Palabras de desarrollo explicadas","intro":"Las palabras que usan los desarrolladores (y los equipos de IA), en lenguaje llano.","search":"Buscar una palabra…","none":"Ninguna palabra coincide.","close":"Cerrar","list":[{"id":"backlog","word":"Backlog","text":"Ideas y trabajo que aún no se ha planificado. Nada de ahí se trabaja hasta que pasa a Por hacer."},{"id":"sprint","word":"Sprint","text":"Un periodo corto de trabajo (a menudo una o dos semanas) con un conjunto acordado de tarjetas por terminar.","also":["sprints"]},{"id":"standup","word":"Stand-up","text":"Una puesta al día rápida: qué hizo cada miembro del equipo, qué hará después y qué se lo impide.","also":["standup","stand-ups","reunión diaria"]},{"id":"bug","word":"Bug","text":"Algo que no funciona como debería.","also":["bugs","error","errores"]},{"id":"test","word":"Prueba","text":"Probar un trabajo terminado para comprobar que hace lo que se pidió, antes de aceptarlo.","also":["pruebas","test","tests"],"noTip":1},{"id":"commit","word":"Commit","text":"Una instantánea guardada del código, con una nota breve de lo que cambió. Siempre puedes volver a una.","also":["commits"]},{"id":"push","word":"Push","text":"Enviar las instantáneas guardadas (commits) de este ordenador a GitHub, para tenerlas respaldadas y compartidas."},{"id":"branch","word":"Rama","text":"Una línea de trabajo separada en el código, para hacer cambios sin tocar la versión principal.","also":["ramas","branch","branches"]},{"id":"merge","word":"Merge","text":"Incorporar los cambios de una rama a la versión principal."},{"id":"repo","word":"Repo","text":"La carpeta de código del proyecto y todo su historial de commits, normalmente también guardada en GitHub.","also":["repositorio"]},{"id":"refactor","word":"Refactorizar","text":"Ordenar el código sin cambiar lo que hace: archivos más pequeños, nombres más claros, menos repetición."},{"id":"deploy","word":"Deploy","text":"Publicar una versión nueva, por ejemplo en un servidor donde la gente la usa."},{"id":"kanban","word":"Kanban","text":"Un tablero con columnas (Por hacer, En curso, Hecho) donde las tarjetas pasan de izquierda a derecha según avanza el trabajo."},{"id":"wip","word":"Límite WIP","text":"Trabajo en curso: el máximo de tarjetas que debería tener una columna, para que el equipo termine las cosas antes de empezar más.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Pedir que se revisen los cambios de una rama y se unan a la versión principal.","also":["PR"]},{"id":"hook","word":"Hook","text":"Un comando pequeño que se ejecuta solo en un momento dado, p. ej. cuando empieza una sesión de IA, para que el equipo oiga tus comentarios.","also":["hooks"]},{"id":"token","word":"Token","text":"La unidad en que se cuenta el uso de IA: más o menos unas pocas letras de texto leídas o escritas. Cuantos menos tokens, más plan te queda.","also":["tokens"]},{"id":"agent","word":"Agente","text":"Una IA que trabaja por su cuenta en una tarea: lee el código, hace cambios, ejecuta comprobaciones e informa.","also":["agentes","agent","agents"]}]}};
